import codecs, re, io, sys, json
cases = {
 'crlf': b'a b\r\nc d\r\n',
 'bom': codecs.BOM_UTF8+b'hi there\n',
 'empty': b'',
 'nonl': b'one\ntwo',
 'cr': b'a\rb\rc',
 'trail': b'a\n\n\n',
 'bom2': codecs.BOM_UTF8*2+b'x',
 'nul': b'a\x00b',
 'uni': 'caf\u00e9 na\u00efve \u0663 \u212a Stra\u00dfe \u0130 \x0b\x0c\x1c\u2028\u2029\x85 end'.encode(),
}
for n,raw in cases.items():
    t = raw.decode('utf-8-sig')
    tm = io.TextIOWrapper(io.BytesIO(raw), encoding='utf-8-sig').read()   # text mode, universal newlines
    print(f'{n:6} lines={len(t.splitlines())} chars_bytes={len(t)} chars_textmode={len(tm)} words={len(re.findall(\"[a-z0-9]+\", t.lower()))}')
t=cases['uni'].decode('utf-8-sig')
print('uni tokens', re.findall('[a-z0-9]+', t.lower()), 'lines', len(t.splitlines()))
print('dotted I lower', repr('\u0130'.lower()), len('\u0130'.lower()), 'Kelvin', re.findall('[a-z0-9]+','\u212a'.lower()))
print('bom2 ->', repr(cases['bom2'].decode('utf-8-sig')))
for bad in (b'\xed\xa0\x80', b'\xff', b'ok \xc3', b'\xef\xbb'):
    try: bad.decode('utf-8-sig'); print(bad,'ok')
    except UnicodeDecodeError: print(bad,'rejected')
print('json non-ascii:', json.dumps({'w':'caf\u00e9'}), '(words are ascii-only so ensure_ascii moot)')
# sort check
from collections import Counter
c = Counter(['b','a','b','a','c']); print(sorted(c.items(), key=lambda kv:(-kv[1], kv[0])))
print('most_common tie:', c.most_common(3))
"@
